// Package model 定义东东电竞 PostgreSQL 持久化模型。
// data 层负责模型读写及事务，biz 层负责用例与状态迁移；不直接把数据库模型作为 API DTO。
package model

import (
	"database/sql"
	"database/sql/driver"
	"encoding/json"
	"fmt"
	"time"
)

// Base 可变业务表的主键与时间；GORM 正常更新时自动维护 UpdatedAt。
// 使用原生 SQL、UpdateColumn 或跳过 hooks 时，仓储仍须显式设置更新时间。
// PostgreSQL 迁移脚本的主键为 GENERATED BY DEFAULT AS IDENTITY，不使用统一软删除。
type Base struct {
	ID        int64     `gorm:"column:id;type:bigint;primaryKey;autoIncrement;comment:主键" json:"id,string"`
	CreatedAt time.Time `gorm:"column:created_at;type:timestamptz;not null;default:CURRENT_TIMESTAMP;autoCreateTime;comment:创建时间" json:"created_at"`
	UpdatedAt time.Time `gorm:"column:updated_at;type:timestamptz;not null;default:CURRENT_TIMESTAMP;autoUpdateTime;comment:更新时间" json:"updated_at"`
}

// EventBase 用于只追加的事件与审计；保持原有三个列，禁止自动修改时间。
// 数据库触发器负责拒绝 UPDATE/DELETE，业务代码只能插入这些事实记录。
type EventBase struct {
	ID        int64     `gorm:"column:id;type:bigint;primaryKey;autoIncrement;comment:主键" json:"id,string"`
	CreatedAt time.Time `gorm:"column:created_at;type:timestamptz;not null;default:CURRENT_TIMESTAMP;autoCreateTime;comment:创建时间" json:"created_at"`
	UpdatedAt time.Time `gorm:"column:updated_at;type:timestamptz;not null;default:CURRENT_TIMESTAMP;autoUpdateTime:false;comment:更新时间" json:"updated_at"`
}

// JSONB 保存合法 JSON；nil 对应 SQL NULL，JSON 字面量 null 与 SQL NULL 不混淆。
// 应用层须进一步检查各字段的 schema、附件存在性与所有权。
type JSONB json.RawMessage

var _ sql.Scanner = (*JSONB)(nil)
var _ driver.Valuer = JSONB(nil)

func (j *JSONB) Scan(value any) error {
	if j == nil {
		return fmt.Errorf("model.JSONB: nil receiver")
	}
	var data []byte
	switch v := value.(type) {
	case nil:
		*j = nil
		return nil
	case []byte:
		data = v
	case string:
		data = []byte(v)
	default:
		return fmt.Errorf("model.JSONB: unsupported SQL type %T", value)
	}
	if !json.Valid(data) {
		return fmt.Errorf("model.JSONB: invalid JSON")
	}
	// Drivers may reuse their []byte buffer after Scan returns.
	*j = append(JSONB(nil), data...)
	return nil
}

func (j JSONB) Value() (driver.Value, error) {
	if j == nil {
		return nil, nil
	}
	if !json.Valid(j) {
		return nil, fmt.Errorf("model.JSONB: invalid JSON")
	}
	// PostgreSQL drivers accept JSON text; do not expose bytea encoding here.
	return string(j), nil
}

func (j JSONB) MarshalJSON() ([]byte, error) {
	if j == nil {
		return []byte("null"), nil
	}
	if !json.Valid(j) {
		return nil, fmt.Errorf("model.JSONB: invalid JSON")
	}
	return append([]byte(nil), j...), nil
}

func (j *JSONB) UnmarshalJSON(data []byte) error { return j.Scan(data) }

func (JSONB) GormDataType() string { return "jsonb" }

// Date 表示不带时间和时区的业务日/渠道账单日，JSON 格式 YYYY-MM-DD。
// 使用 NewDate 或解析渠道的明确日期，不把数据库日期误按 UTC 跨日换算。
type Date struct{ time.Time }

var _ sql.Scanner = (*Date)(nil)
var _ driver.Valuer = Date{}

func NewDate(year int, month time.Month, day int) Date {
	return Date{Time: time.Date(year, month, day, 0, 0, 0, 0, time.UTC)}
}

func (d *Date) Scan(value any) error {
	if d == nil {
		return fmt.Errorf("model.Date: nil receiver")
	}
	var t time.Time
	var err error
	switch v := value.(type) {
	case time.Time:
		t = v
	case string:
		t, err = time.Parse(time.DateOnly, v)
	case []byte:
		t, err = time.Parse(time.DateOnly, string(v))
	default:
		return fmt.Errorf("model.Date: unsupported SQL type %T", value)
	}
	if err != nil {
		return fmt.Errorf("model.Date: %w", err)
	}
	*d = NewDate(t.Year(), t.Month(), t.Day())
	return nil
}

func (d Date) Value() (driver.Value, error) {
	if d.IsZero() {
		return nil, fmt.Errorf("model.Date: zero business date")
	}
	return d.Format(time.DateOnly), nil
}

func (d Date) MarshalJSON() ([]byte, error) {
	if d.IsZero() {
		return []byte("null"), nil
	}
	return json.Marshal(d.Format(time.DateOnly))
}

func (d *Date) UnmarshalJSON(data []byte) error {
	var value string
	if err := json.Unmarshal(data, &value); err != nil {
		return err
	}
	return d.Scan(value)
}

func (Date) GormDataType() string { return "date" }
